      "rationale": "These spans establish incomplete reconstruction, controlled reduction tests, the reproduction pattern and treatment of unresolved outcomes."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C051.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
